<script lang="ts">
	// @ts-expect-error — generated by Wails
	import { LogInfo } from '@wails/runtime/runtime';
	import { installState } from '$lib/store.svelte';
	import { confirmInstallation } from '$lib/navigation';
	import { t } from '$lib/i18n';
	import './dialog.css';

	let {
		// Drives visibility. Defaults to (and binds back to) the shared
		// installation-confirmation flag so the Confirmation page can keep using
		// `<ConfirmDialog />` unchanged. Pages with their own state pass a bindable
		// boolean instead, e.g. `show={showDeleteDialog}`.
		show = $bindable(installState.showConfirmDialog),
		title = t('dialog.confirm.title'),
		// No default here: the installation message is mode-aware and computed
		// reactively below (see installationMessage). Callers with their own copy
		// (e.g. the delete dialog) still pass an explicit `message`.
		message,
		cancelLabel = t('dialog.confirm.cancel'),
		confirmLabel = t('dialog.confirm.confirm'),
		// Delete dialog historically had no warning glyph; opt out with show-icon={false}.
		showIcon = true,
		// Validation modal uses OK-only (no cancel).
		showCancel = true,
		// When provided, these replace the default installation flow (which
		// dispatches 'go-next-confirmed' and advances the wizard).
		onConfirm,
		onCancel,
	}: {
		show?: boolean;
		title?: string;
		message?: string;
		cancelLabel?: string;
		confirmLabel?: string;
		showIcon?: boolean;
		showCancel?: boolean;
		onConfirm?: () => void;
		onCancel?: () => void;
	} = $props();

	// Installation confirmation copy adapts to the install mode. Automatic installs
	// wipe the whole disk; manual (dualboot-safe) installs only touch the chosen
	// Boot and Root partitions and leave the rest of the disk intact.
	const installationMessage = $derived.by(() =>
		installState.manualMode
			? t('dialog.confirm.messageManual', { model: installState.disk?.model || 'Unknown' })
			: t('dialog.confirm.message', { model: installState.disk?.model || 'Unknown' }),
	);

	// Fall back to the reactive installation message when the caller didn't pass
	// its own (i.e. the standard installation confirmation dialog).
	const effectiveMessage = $derived(message ?? installationMessage);

	function handleConfirm(): void {
		show = false;
		if (onConfirm) {
			onConfirm();
		} else {
			LogInfo('[ConfirmDialog] User confirmed installation');
			confirmInstallation();
			document.dispatchEvent(new CustomEvent('go-next-confirmed'));
		}
	}

	// Dismiss the dialog: hide it and run the caller's cancel side effect (if any).
	// Used by both the Cancel button and the backdrop/Escape handler.
	function handleCancel(): void {
		show = false;
		if (onCancel) {
			onCancel();
		}
	}
</script>

{#if show}
	<div
		class="dialog-overlay"
		role="presentation"
		onclick={handleCancel}
		onkeydown={(e) => { if (e.key === 'Escape') handleCancel(); }}
	>
		<div
			class="dialog"
			role="dialog"
			aria-modal="true"
			aria-labelledby="dialog-title"
			tabindex="-1"
			onclick={(e) => e.stopPropagation()}
			onkeydown={(e) => e.stopPropagation()}
		>
			{#if showIcon}
				<div class="dialog-icon">
					<svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
						<path d="M12 2L2 20H22L12 2Z" fill="var(--color-danger)" stroke="var(--color-danger)" stroke-width="1.5" stroke-linejoin="round"/>
						<line x1="12" y1="8" x2="12" y2="13" stroke="white" stroke-width="2" stroke-linecap="round"/>
						<circle cx="12" cy="16.5" r="1" fill="white"/>
					</svg>
				</div>
			{/if}
			<h2 id="dialog-title" class="dialog-title">{title}</h2>
			<p class="dialog-message">
				{@html effectiveMessage}
			</p>
			<div class="dialog-actions">
				{#if showCancel}
					<button type="button" class="btn-cancel" onclick={handleCancel}>
						{cancelLabel}
					</button>
				{/if}
				<button type="button" class="btn-confirm" onclick={handleConfirm}>
					{confirmLabel}
				</button>
			</div>
		</div>
	</div>
{/if}

<style>
	/* Shared dialog chrome lives in ./dialog.css. */
	.dialog-icon {
		text-align: center;
		margin-bottom: var(--spacing-md);
	}

	.dialog-icon svg {
		width: 64px;
		height: 64px;
	}

	.dialog-message {
		margin: 0 0 24px;
		font-size: var(--font-size-md);
		color: var(--color-text-muted);
		line-height: 1.6;
		text-align: center;
	}
</style>
